function autorizar(...perfisPermitidos) {
    return (req, res, next) => {
        if (!perfisPermitidos.includes(req.usuario.perfil)) {
            return res.status(403).json({ erro: "Acesso negado para o seu perfil." });
        }
        next();
    };
}

module.exports = autorizar;

